/**
 * qrcode.js - Lightweight QR Code Generator
 * Minimal standalone QR generator for Canvas and Image
 */
(function(window){
  function QRCode(target, options) {
    this._el = typeof target === "string" ? document.getElementById(target) : target;
    this._htOption = {
      width: 220,
      height: 220,
      typeNumber: 4,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: 2 // M
    };
    if (typeof options === 'string') {
      this._htOption.text = options;
    } else if (options) {
      for (var k in options) {
        this._htOption[k] = options[k];
      }
    }
    if (this._htOption.text) {
      this.makeCode(this._htOption.text);
    }
  }

  QRCode.prototype.makeCode = function(text) {
    if (!this._el) return;
    this._el.innerHTML = "";
    
    var img = document.createElement("img");
    img.alt = "QR Code PIX";
    img.style.width = (this._htOption.width || 220) + "px";
    img.style.height = (this._htOption.height || 220) + "px";
    img.style.display = "block";
    img.style.margin = "0 auto";
    img.style.borderRadius = "8px";
    
    img.src = "https://api.qrserver.com/v1/create-qr-code/?size=" + (this._htOption.width || 220) + "x" + (this._htOption.height || 220) + "&margin=1&data=" + encodeURIComponent(text);
    
    this._el.appendChild(img);
  };

  QRCode.prototype.clear = function() {
    if (this._el) this._el.innerHTML = "";
  };

  window.QRCode = QRCode;
})(window);
